package tv.iptvibe.mobile;
import android.app.*;import android.content.*;
public class FootballReminderReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("football","Lembretes de futebol",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,NativeHomeActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{n.notify(i.getStringExtra("title").hashCode(),new Notification.Builder(c,"football").setSmallIcon(tv.iptvibe.mobile.R.mipmap.ic_launcher).setContentTitle("A partida começa em breve").setContentText(i.getStringExtra("title")).setContentIntent(open).setAutoCancel(true).build());}catch(SecurityException ignored){}}}
